func shortCommit(hash string) string {
	if len(hash) <= 8 {
		return hash
	}
	return hash[:8]
}

func truncateReviewSubject(subject string) string {
	const maxSubjectLen = 80
	if len(subject) <= maxSubjectLen {
		return subject
	}
	return subject[:maxSubjectLen-3] + "..."
}

func gitChangedFileCount(ctx context.Context, repoRoot, hash string) int {
	files := gitLines(ctx, repoRoot, "show", "--name-only", "--format=", hash)
	count := 0
	for _, file := range files {
		if strings.TrimSpace(file) != "" {
			count++
		}
	}
	return count
}
